PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS release_workspaces(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES commerce_members(id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL,body_hash TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,approved_revision INTEGER,approved_hash TEXT,archived_at INTEGER,create_request TEXT NOT NULL,create_signature TEXT NOT NULL,write_id TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(owner_id,create_request));
CREATE TABLE IF NOT EXISTS release_members(workspace_id TEXT NOT NULL REFERENCES release_workspaces(id) ON DELETE CASCADE,member_id TEXT NOT NULL REFERENCES commerce_members(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('owner','editor','viewer')),joined_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,member_id));
CREATE TABLE IF NOT EXISTS release_revisions(workspace_id TEXT NOT NULL REFERENCES release_workspaces(id) ON DELETE CASCADE,revision INTEGER NOT NULL,body TEXT NOT NULL,body_hash TEXT NOT NULL,member_id TEXT REFERENCES commerce_members(id) ON DELETE SET NULL,write_id TEXT NOT NULL,saved_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,revision),UNIQUE(workspace_id,write_id));
CREATE TABLE IF NOT EXISTS release_reviews(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES release_workspaces(id) ON DELETE CASCADE,revision INTEGER NOT NULL,body_hash TEXT NOT NULL,member_id TEXT REFERENCES commerce_members(id) ON DELETE SET NULL,decision TEXT NOT NULL CHECK(decision IN('comment','changes_requested','approve')),note TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS release_invites(id TEXT PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,workspace_id TEXT NOT NULL REFERENCES release_workspaces(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('editor','viewer')),created_by TEXT NOT NULL REFERENCES commerce_members(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,revoked_at INTEGER,used_by TEXT REFERENCES commerce_members(id) ON DELETE SET NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS release_oauth_states(state_hash TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES commerce_members(id) ON DELETE CASCADE,session_hash TEXT NOT NULL,nonce_hash TEXT NOT NULL,verifier_cipher TEXT NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS release_connections(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES commerce_members(id) ON DELETE CASCADE,channel_id TEXT NOT NULL,title TEXT NOT NULL,tokens_cipher TEXT NOT NULL,scopes TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1,access_expires_at INTEGER NOT NULL,checked_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(member_id,channel_id));
CREATE TABLE IF NOT EXISTS release_operations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES release_workspaces(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES commerce_members(id) ON DELETE CASCADE,connection_id TEXT REFERENCES release_connections(id) ON DELETE SET NULL,channel_id TEXT NOT NULL,episode_id TEXT NOT NULL,revision INTEGER NOT NULL,applied_revision INTEGER,file_identity TEXT NOT NULL,file_fingerprint TEXT NOT NULL,total_bytes INTEGER NOT NULL,offset INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,action TEXT NOT NULL DEFAULT 'upload',uncertain INTEGER NOT NULL DEFAULT 0,video_id TEXT,processing TEXT,remote_etag TEXT,remote_cipher TEXT,session_cipher TEXT,snapshot TEXT NOT NULL,request_id TEXT NOT NULL,request_signature TEXT NOT NULL,lease_id TEXT,lease_until INTEGER,error_code TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,remote_checked_at INTEGER,remote_expires_at INTEGER,UNIQUE(owner_id,request_id),UNIQUE(workspace_id,episode_id,file_fingerprint,channel_id));
CREATE TABLE IF NOT EXISTS release_actions(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES release_operations(id) ON DELETE CASCADE,member_id TEXT NOT NULL REFERENCES commerce_members(id) ON DELETE CASCADE,revision INTEGER NOT NULL,kind TEXT NOT NULL,request_id TEXT NOT NULL,signature TEXT NOT NULL,status TEXT NOT NULL,expected_etag TEXT,payload_cipher TEXT,error_code TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(operation_id,request_id));
CREATE INDEX IF NOT EXISTS release_owned_active ON release_workspaces(owner_id) WHERE archived_at IS NULL;
CREATE INDEX IF NOT EXISTS release_member_access ON release_members(member_id,workspace_id);
CREATE INDEX IF NOT EXISTS release_operation_workspace ON release_operations(workspace_id,updated_at);
CREATE INDEX IF NOT EXISTS release_oauth_expiry ON release_oauth_states(expires_at);
